mapper.insert:
/* AppReq07Mapper.insertAttdReq */
INSERT INTO TB_USER_ATTD_REQ (
      REQ_ID
    , CMPNY_CD
    , SITE_CD
    , USER_CD
    , REQ_TYPE
    , TARGET_ID
    , REQ_STATUS
    , REQ_REASON
    , WORK_YMD
    , NODE_CD
    , WORK_SEQ
    , START_DATE
    , START_TIME
    , END_DATE
    , END_TIME
    , OT_TYPE
    , SCH_CD
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{reqId}
    , #{cmpnyCd}
    , #{siteCd}
    , #{userCd}
    , #{reqType}
    , #{targetId}
    , #{reqStatus}
    , #{reqReason}
    , #{workYmd}
    , #{nodeCd}
    , #{workSeq}
    , #{startDate}
    , #{startTime}
    , #{endDate}
    , #{endTime}
    , #{otType}
    , #{schCd}
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.select:
/* AppReq07Mapper.countDuplicateReq */
SELECT COUNT(1)
  FROM TB_USER_ATTD_REQ A
 WHERE A.CMPNY_CD   = #{cmpnyCd}
   AND A.SITE_CD    = #{siteCd}
   AND A.USER_CD    = #{userCd}
   AND A.WORK_YMD   = #{workYmd}
   AND A.REQ_TYPE   = #{reqType}
   AND A.REQ_STATUS = '01'
   AND A.DEL_YN     = 'N'

/* AppReq07Mapper.selectExistingAttdId */
SELECT A.ATTD_ID
  FROM TB_USER_ATTD_MGMT A
 WHERE A.CMPNY_CD = #{cmpnyCd}
   AND A.SITE_CD  = #{siteCd}
   AND A.USER_CD  = #{userCd}
   AND A.WORK_YMD = #{workYmd}
   AND A.WORK_SEQ = #{workSeq}
   AND A.DEL_YN   = 'N'
 LIMIT 1
